package dev.zomboid.autopsy;import java.util.*;import net.minecraft.client.*;public class Checks {static int n;static void check(boolean b){n++;if(!b)throw new AssertionError(n);}public static void main(String[] args){check(!Autopsy.serious(.9,Set.of("cut")));check(Autopsy.serious(.2,Set.of("trauma")));check(Autopsy.serious(1,Set.of("fracture")));check(Autopsy.serious(.8,Set.of("bullet")));check(Autopsy.mechanism("bleeding","",false,false,false).contains("registrada"));check(Autopsy.mechanism("generic","",false,false,false).equals("Mecanismo no determinado"));check(Autopsy.mechanism("mob","",true,false,true).contains("probable"));check(!Autopsy.mechanism("mob","",false,false,true).contains("Paro"));Minecraft mc=Minecraft.M;SpawnView.tick(null);check(mc.options.camera==CameraType.FIRST_PERSON&&!com.cleannrooster.dungeons_iso.mod.Mod.enabled);check(mc.mouseHandler.released==1&&mc.mouseHandler.grabbed==1);mc.options.camera=CameraType.THIRD_PERSON_BACK;SpawnView.tick(null);check(mc.options.camera==CameraType.THIRD_PERSON_BACK);mc.player=new Object();SpawnView.tick(null);check(mc.options.camera==CameraType.FIRST_PERSON);System.out.println("Passed "+n+" autopsy classification and respawn checks (API doubles)");}}
